def group_comparisons(items, groups, *, minimum: int = 2) -> dict:
    """Aggregate pairwise :func:`compare_summaries` results per group.

    ``items`` follows the :func:`aggregate_comparisons` contract: a list
    of at least two mappings, each with exactly the keys ``name, result``
    in that order.  ``name`` is a unique non-empty str and ``result`` is a
    complete :func:`compare_summaries` result (schema
    ``climate-grid/gec-v1``), validated against that contract.  Every
    item's result must share the same ``scenarios`` axis in the same
    order; it is taken from the first item's result.

    ``groups`` is a non-empty list of mappings, each with exactly the
    keys ``name, labels`` in that order.  ``name`` is a unique non-empty
    str and ``labels`` is a non-empty list of distinct non-empty str
    values.  Across all groups the labels must be unique and cover every
    item name exactly once, partitioning the item names.  ``minimum``
    must be a non-bool positive int.

    For every group (in group order) and scenario (in scenario order),
    the rows of the group's labelled items whose ``mean``, ``slope``,
    ``uncertainty`` and ``band`` are all present are collected and
    ``count`` is the number ``n`` of collected rows.  When
    ``n < minimum``, ``mean``, ``slope``, ``uncertainty`` and ``band``
    are all ``None``; otherwise, for each of the two columns, ``mean``
    is the mean of the collected means, ``slope`` is the mean of the
    collected slopes, writing the collected uncertainties as ``u``,
    ``uncertainty`` is ``hypot(*u) / n`` and ``band`` is the
    ``[min lower bound, max upper bound]`` of the collected bands.

    The returned mapping uses the key order ``schema, groups, scenarios,
    data``; ``schema`` is ``climate-grid/gec-group-v1``.  ``groups``
    lists the group names in group order and ``scenarios`` echoes the
    shared scenario axis in its original order.  ``data`` is a nested
    mapping keyed by group then scenario (in their original orders); each
    row uses the key order ``group, scenario, count, mean, slope,
    uncertainty, band``.  ``count`` is an int and, when present,
    ``mean``, ``slope`` and ``uncertainty`` are two-item float lists
    while ``band`` is a two-item list of ``[lower, upper]`` bounds, or
    all four are ``None``.  Every float is ``round(x, 12)`` with
    negative zero normalized to ``0.0`` and a non-finite derived value
    raises ``ValueError``.  The inputs are not modified.

    Raises ``TypeError`` for wrong container/argument types and
    ``ValueError`` for any other contract violation, including
    non-finite values in an item result.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 2:
        raise ValueError("items must contain at least 2 items")

    labels: list[str] = []
    validated: list[list[dict]] = []
    seen_names: set[str] = set()
    first_scenarios: list[str] = []
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _EVOLUTION_SUMMARY_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys name, result in order"
            )

        name = item["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate items name: {name!r}")
        seen_names.add(name)

        scenarios, rows = _validate_compare_summaries_result(
            item["result"], where=f"{where}.result"
        )
        if not validated:
            first_scenarios = scenarios
        elif scenarios != first_scenarios:
            raise ValueError(
                "all items must share the same result scenarios in the "
                "same order, taken from the first item"
            )

        labels.append(name)
        validated.append(rows)

    if not isinstance(groups, list):
        raise TypeError("groups must be a list")
    if len(groups) == 0:
        raise ValueError("groups must be non-empty")

    group_names: list[str] = []
    group_labels: list[list[str]] = []
    seen_group_names: set[str] = set()
    seen_labels: set[str] = set()
    for group_index, group in enumerate(groups):
        where = f"groups[{group_index}]"
        if not isinstance(group, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(group.keys()) != _EVOLUTION_GROUP_COMPARISONS_GROUP_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys name, labels in order"
            )

        group_name = group["name"]
        if not isinstance(group_name, str):
            raise TypeError(f"{where}.name must be a str")
        if group_name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if group_name in seen_group_names:
            raise ValueError(f"duplicate groups name: {group_name!r}")
        seen_group_names.add(group_name)

        member_labels = group["labels"]
        if not isinstance(member_labels, list):
            raise TypeError(f"{where}.labels must be a list")
        if len(member_labels) == 0:
            raise ValueError(f"{where}.labels must be non-empty")
        for label_index, label in enumerate(member_labels):
            label_where = f"{where}.labels[{label_index}]"
            if not isinstance(label, str):
                raise TypeError(f"{label_where} must be a str")
            if label == "":
                raise ValueError(f"{label_where} must be non-empty")
            if label in seen_labels:
                raise ValueError(f"duplicate groups label: {label!r}")
            if label not in seen_names:
                raise ValueError(
                    f"{label_where} must name an items entry: {label!r}"
                )
            seen_labels.add(label)

        group_names.append(group_name)
        group_labels.append(list(member_labels))

    if seen_labels != seen_names:
        missing = [name for name in labels if name not in seen_labels]
        raise ValueError(
            "groups labels must cover every items name without duplicates; "
            f"uncovered items name: {missing}"
        )

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    rows_by_name = {
        name: rows for name, rows in zip(labels, validated)
    }

    data: dict[str, dict[str, dict]] = {}
    for group_name, member_labels in zip(group_names, group_labels):
        data[group_name] = {}
        for scenario_index, scenario in enumerate(first_scenarios):
            means: tuple[list, list] = ([], [])
            slopes: tuple[list, list] = ([], [])
            uncertainties: tuple[list, list] = ([], [])
            lower_bounds: tuple[list, list] = ([], [])
            upper_bounds: tuple[list, list] = ([], [])
            for member_name in member_labels:
                row = rows_by_name[member_name][scenario_index]
                if (
                    row["mean"] is None
                    or row["slope"] is None
                    or row["uncertainty"] is None
                    or row["band"] is None
                ):
                    continue
                for column in range(2):
                    means[column].append(float(row["mean"][column]))
                    slopes[column].append(float(row["slope"][column]))
                    uncertainties[column].append(
                        float(row["uncertainty"][column])
                    )
                    lower_bounds[column].append(float(row["band"][column][0]))
                    upper_bounds[column].append(float(row["band"][column][1]))

            count = len(means[0])

            if count < minimum:
                mean = None
                slope = None
                uncertainty = None
                band = None
            else:
                mean = []
                slope = []
                uncertainty = []
                band = []
                for column in range(2):
                    try:
                        mean_value = math.fsum(means[column]) / count
                        slope_value = math.fsum(slopes[column]) / count
                        uncertainty_value = (
                            math.hypot(*uncertainties[column]) / count
                        )
                        lower_value = min(lower_bounds[column])
                        upper_value = max(upper_bounds[column])
                    except OverflowError:
                        raise ValueError(
                            f"data[{group_name!r}][{scenario!r}] results "
                            "must be finite"
                        ) from None
                    if not all(
                        _is_finite(value)
                        for value in (
                            mean_value,
                            slope_value,
                            uncertainty_value,
                            lower_value,
                            upper_value,
                        )
                    ):
                        raise ValueError(
                            f"data[{group_name!r}][{scenario!r}] results "
                            "must be finite"
                        )
                    mean.append(_round_output(mean_value))
                    slope.append(_round_output(slope_value))
                    uncertainty.append(_round_output(uncertainty_value))
                    band.append(
                        [
                            _round_output(lower_value),
                            _round_output(upper_value),
                        ]
                    )

            data[group_name][scenario] = {
                "group": group_name,
                "scenario": scenario,
                "count": count,
                "mean": mean,
                "slope": slope,
                "uncertainty": uncertainty,
                "band": band,
            }

    return {
        "schema": _EVOLUTION_GROUP_COMPARISONS_SCHEMA,
        "groups": group_names,
        "scenarios": list(first_scenarios),
        "data": data,
    }


_EVOLUTION_GROUP_RANK_SCHEMA = "climate-grid/gec-group-rank-v1"
_EVOLUTION_GROUP_RANK_RESULT_KEYS = (
    "schema",
    "reference",
    "groups",
    "scenarios",
    "data",
)
_EVOLUTION_GROUP_RANK_ROW_KEYS = (
    "scenario",
    "group",
    "count",
    "mean",
    "slope",
    "uncertainty",
    "rank",
)


def _validate_group_comparisons_result(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], dict[str, dict[str, dict]]]:
    """Validate a complete :func:`group_comparisons` result.

    Returns the group names, the scenario axis and the ``data`` rows,
    checking the ``climate-grid/gec-group-v1`` contract: key order, the
    group and scenario axes, the group-then-scenario nesting and the
    internal ``count``/``mean``/``slope``/``uncertainty``/``band``
    invariants of every row.  ``mean``, ``slope``, ``uncertainty`` and
    ``band`` are ``None`` together; when present they require a
    positive ``count`` and are two-item columns with non-negative
    ``uncertainty`` entries and ``band`` bounds in ``[lower, upper]``
    order.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _EVOLUTION_GROUP_COMPARISONS_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, groups, "
            "scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _EVOLUTION_GROUP_COMPARISONS_SCHEMA:
        raise ValueError(
            f"{where}.schema must be "
            f"{_EVOLUTION_GROUP_COMPARISONS_SCHEMA!r}"
        )

    groups = _validate_string_list(
        result["groups"], f"{where}.groups", minimum=1
    )
    scenarios = _validate_string_list(
        result["scenarios"], f"{where}.scenarios", minimum=1
    )

    data = result["data"]
    if not isinstance(data, dict):
        raise TypeError(f"{where}.data must be a dict")
    if tuple(data.keys()) != tuple(groups):
        raise ValueError(
            f"{where}.data must be keyed by group in group order"
        )

    out_data: dict[str, dict[str, dict]] = {}
    for group in groups:
        group_where = f"{where}.data[{group!r}]"
        group_data = data[group]
        if not isinstance(group_data, dict):
            raise TypeError(f"{group_where} must be a dict")
        if tuple(group_data.keys()) != tuple(scenarios):
            raise ValueError(
                f"{group_where} must be keyed by scenario in scenario "
                "order"
            )
        out_data[group] = {}
        for scenario_index, scenario in enumerate(scenarios):
            row_where = f"{group_where}[{scenario!r}]"
            row = group_data[scenario]
            if not isinstance(row, dict):
                raise TypeError(f"{row_where} must be a dict")
            if tuple(row.keys()) != _EVOLUTION_GROUP_COMPARISONS_ROW_KEYS:
                raise ValueError(
                    f"{row_where} must have exactly the keys group, "
                    "scenario, count, mean, slope, uncertainty, band in "
                    "order"
                )

            row_group = row["group"]
            if not isinstance(row_group, str):
                raise TypeError(f"{row_where}.group must be a str")
            if row_group != group:
                raise ValueError(
                    f"{row_where}.group must be {group!r} for its group "
                    "position"
                )

            row_scenario = row["scenario"]
            if not isinstance(row_scenario, str):
                raise TypeError(f"{row_where}.scenario must be a str")
            if row_scenario != scenario:
                raise ValueError(
                    f"{row_where}.scenario must be {scenario!r} for its "
                    "scenario position"
                )

            count = row["count"]
            if not isinstance(count, int) or isinstance(count, bool):
                raise TypeError(f"{row_where}.count must be a non-bool int")
            if count < 0:
                raise ValueError(f"{row_where}.count must be non-negative")

            mean = row["mean"]
            slope = row["slope"]
            uncertainty = row["uncertainty"]
            band = row["band"]
            if (
                mean is None
                or slope is None
                or uncertainty is None
                or band is None
            ):
                if (
                    mean is not None
                    or slope is not None
                    or uncertainty is not None
                    or band is not None
                ):
                    raise ValueError(
                        f"{row_where}.mean, {row_where}.slope, "
                        f"{row_where}.uncertainty and {row_where}.band must "
                        "be None together"
                    )
                out_data[group][scenario] = row
                continue

            if count < 1:
                raise ValueError(
                    f"{row_where}.mean, {row_where}.slope, "
                    f"{row_where}.uncertainty and {row_where}.band must be "
                    "None when count is zero"
                )

            for column_key, column in (
                ("mean", mean),
                ("slope", slope),
                ("uncertainty", uncertainty),
            ):
                if not isinstance(column, list):
                    raise TypeError(f"{row_where}.{column_key} must be a list")
                if len(column) != 2:
                    raise ValueError(
                        f"{row_where}.{column_key} must contain exactly 2 "
                        "items"
                    )
                for column_index, value in enumerate(column):
                    _validate_number(
                        value,
                        f"{row_where}.{column_key}[{column_index}]",
                        nullable=False,
                    )
                    if column_key == "uncertainty" and value < 0:
                        raise ValueError(
                            f"{row_where}.uncertainty[{column_index}] must "
                            "be non-negative"
                        )

            if not isinstance(band, list):
                raise TypeError(f"{row_where}.band must be a list")
            if len(band) != 2:
                raise ValueError(
                    f"{row_where}.band must contain exactly 2 items"
                )
            for column_index, bounds in enumerate(band):
                bounds_where = f"{row_where}.band[{column_index}]"
                if not isinstance(bounds, list):
                    raise TypeError(f"{bounds_where} must be a list")
                if len(bounds) != 2:
                    raise ValueError(
                        f"{bounds_where} must contain exactly 2 items"
                    )
                _validate_number(
                    bounds[0], f"{bounds_where}[0]", nullable=False
                )
                _validate_number(
                    bounds[1], f"{bounds_where}[1]", nullable=False
                )
                if bounds[0] > bounds[1]:
                    raise ValueError(
                        f"{bounds_where} must be in [lower, upper] order"
                    )

            out_data[group][scenario] = row

    return groups, scenarios, out_data

