        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _GROUP_RANK_STABILITY_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, reference, "
            "groups, scenarios, data in order"
        )

